import{_ as r,o as a,c as e,a2 as l}from"./chunks/framework.DnrXFDHb.js";const f=JSON.parse('{"title":"精选教程","description":"精选 AI 基础、LLM、Prompt、ComfyUI 与 LoRA 教程，按官方优先、版本匹配和可验证原则筛选学习资料。","frontmatter":{"description":"精选 AI 基础、LLM、Prompt、ComfyUI 与 LoRA 教程，按官方优先、版本匹配和可验证原则筛选学习资料。"},"headers":[],"relativePath":"resources/tutorials.md","filePath":"resources/tutorials.md","lastUpdated":1788365664000}'),o={name:"resources/tutorials.md"};function i(s,t,n,h,u,g){return a(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="精选教程" tabindex="-1">精选教程 <a class="header-anchor" href="#精选教程" aria-label="Permalink to &quot;精选教程&quot;">​</a></h1><blockquote><p><strong>一句话结论：</strong> 优先跟官方文档、官方示例和长期维护的课程；社区教程只作补充，遇到版本差异以官方资料为准——挑对教程只是开始，把教程跟完并变成自己的练习才算学会。</p></blockquote><p>本页链接与描述核对于 2026 年 9 月；教程与版本更新较快，使用前请以官方页面为准。</p><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li>已阅读 <a href="/resources/websites">常用网站</a>，知道官方课程、模型平台和官方文档各解决什么问题。</li><li>不要求已安装 ComfyUI、WebUI 或任何编程环境；本页讲怎么挑教程、怎么跟教程，不替代教程本身。</li><li>先接受一个边界：教程与版本更新很快，本页条目以官方稳定来源为主，遇到描述与实际页面不一致时，以官方当前页面为准。</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完后，你应该能够：</p><ul><li>按自己的目标（补概念、学工具、学训练）选出对应类型的教程。</li><li>用发布时间、版本标注和来源可信度判断一篇教程是否还值得跟。</li><li>按“先跑通最小流程、再逐步加环节”的顺序安排 AI 绘画的学习路径。</li><li>把跟完的教程转化为可复查的笔记与练习产出。</li><li>在社区教程与官方资料说法冲突时，判断以哪边为准。</li></ul><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="如何按教程类型选" tabindex="-1">如何按教程类型选 <a class="header-anchor" href="#如何按教程类型选" aria-label="Permalink to &quot;如何按教程类型选&quot;">​</a></h3><p>教程大体分三类：<strong>概念课程</strong>补理论，<strong>工具实操</strong>练上手，<strong>模型与训练</strong>进阶。零基础先从概念课程或官方入门文档起步，不要一上来就照抄进阶训练脚本。下面按类型列出精选条目。</p><h4 id="llm-理论与实践" tabindex="-1">LLM 理论与实践 <a class="header-anchor" href="#llm-理论与实践" aria-label="Permalink to &quot;LLM 理论与实践&quot;">​</a></h4><ul><li><p><strong>Google LLM 入门课程</strong>（地址：<a href="https://developers.google.com/machine-learning/crash-course/llm" target="_blank" rel="noreferrer">https://developers.google.com/machine-learning/crash-course/llm</a>）</p><ul><li>从 Token、上下文和 Transformer 开始理解大语言模型，适合读完本站 <a href="/ai/basics">AI 基础概念</a> 后继续学习。</li><li>官方课程会持续更新，概念和示例以当前页面为准。</li></ul></li><li><p><strong>Hugging Face LLM Course</strong>（地址：<a href="https://huggingface.co/learn/llm-course/chapter1/1" target="_blank" rel="noreferrer">https://huggingface.co/learn/llm-course/chapter1/1</a>）</p><ul><li>系统学习 Transformer、Tokenizer、推理、微调和模型使用，配合 Hugging Face 模型、数据集和代码示例进行实践。</li><li>课程以英文和 Python 为主，适合已经理解 <a href="/llm/basics">大模型入门</a> 的读者。</li></ul></li><li><p><strong>Hugging Face Agents Course</strong>（地址：<a href="https://huggingface.co/learn/agents-course/en/unit0/introduction" target="_blank" rel="noreferrer">https://huggingface.co/learn/agents-course/en/unit0/introduction</a>）</p><ul><li>学习 Agent、工具调用、Agentic RAG 和评估，配合本站 <a href="/llm/rag-agent">RAG 与 Agent</a> 理解实践流程。</li><li>框架和课程依赖变化较快，运行代码前确认当前单元版本。</li></ul></li></ul><h4 id="comfyui-入门" tabindex="-1">ComfyUI 入门 <a class="header-anchor" href="#comfyui-入门" aria-label="Permalink to &quot;ComfyUI 入门&quot;">​</a></h4><ul><li><p><strong>ComfyUI 官方中文文档</strong>（地址：<a href="https://docs.comfy.org/zh" target="_blank" rel="noreferrer">https://docs.comfy.org/zh</a>）</p><ul><li>了解 ComfyUI 的界面、节点和基础概念，查找官方维护的中文教程入口。</li><li>遇到社区教程说法不一致时，用官方文档做基准。</li></ul></li><li><p><strong>文生图教程</strong>（地址：<a href="https://docs.comfy.org/zh/tutorials/basic/text-to-image" target="_blank" rel="noreferrer">https://docs.comfy.org/zh/tutorials/basic/text-to-image</a>）</p><ul><li>跑通最基础的 text-to-image 流程，理解 checkpoint、prompt、采样器和输出节点之间的关系。</li><li>适合第一次接触 ComfyUI 的用户。</li></ul></li><li><p><strong>工作流模板</strong>（地址：<a href="https://docs.comfy.org/zh/interface/features/template" target="_blank" rel="noreferrer">https://docs.comfy.org/zh/interface/features/template</a>）</p><ul><li>学习如何复用模板，区分模板、工作流和单个节点设置。</li><li>适合已经能打开 ComfyUI、但还不会管理流程的人。</li></ul></li></ul><h4 id="comfyui-工作流" tabindex="-1">ComfyUI 工作流 <a class="header-anchor" href="#comfyui-工作流" aria-label="Permalink to &quot;ComfyUI 工作流&quot;">​</a></h4><ul><li><p><strong>LoRA 教程</strong>（地址：<a href="https://docs.comfy.org/zh/tutorials/basic/lora" target="_blank" rel="noreferrer">https://docs.comfy.org/zh/tutorials/basic/lora</a>）</p><ul><li>学习在 ComfyUI 中加载 LoRA，理解 LoRA 权重和基础模型的关系。</li><li>排查 LoRA 不生效、风格过强或模型不匹配的问题。</li></ul></li><li><p><strong>ControlNet 教程</strong>（地址：<a href="https://docs.comfy.org/zh/tutorials/controlnet/controlnet" target="_blank" rel="noreferrer">https://docs.comfy.org/zh/tutorials/controlnet/controlnet</a>）</p><ul><li>学习用参考图控制姿势、结构或边缘，理解 ControlNet 不是单纯提示词增强，而是图像条件控制。</li><li>适合开始做可控构图和图生图流程时阅读。</li></ul></li><li><p><strong>ComfyUI 官方示例工作流</strong>（地址：<a href="https://comfyanonymous.github.io/ComfyUI_examples/" target="_blank" rel="noreferrer">https://comfyanonymous.github.io/ComfyUI_examples/</a>）</p><ul><li>查看可直接参考的官方示例流程，学习不同任务需要哪些节点组合。</li><li>对照自己的工作流排查节点缺失或连接错误。</li></ul></li></ul><h4 id="webui-a1111" tabindex="-1">WebUI / A1111 <a class="header-anchor" href="#webui-a1111" aria-label="Permalink to &quot;WebUI / A1111&quot;">​</a></h4><ul><li><p><strong>AUTOMATIC1111 官方 Wiki</strong>（地址：<a href="https://github.com/AUTOMATIC1111/stable-diffusion-webui/wiki" target="_blank" rel="noreferrer">https://github.com/AUTOMATIC1111/stable-diffusion-webui/wiki</a>）</p><ul><li>查找 Stable Diffusion WebUI 的官方说明，理解 WebUI 的功能入口、扩展和参数。</li><li>适合使用 A1111 而不是 ComfyUI 的用户。</li></ul></li><li><p><strong>功能说明</strong>（地址：<a href="https://github.com/AUTOMATIC1111/stable-diffusion-webui/wiki/Features" target="_blank" rel="noreferrer">https://github.com/AUTOMATIC1111/stable-diffusion-webui/wiki/Features</a>）</p><ul><li>查看 WebUI 主要功能列表，对照界面理解 txt2img、img2img、inpaint、extras 等模块。</li><li>学习参数含义时作为索引使用。</li></ul></li></ul><h4 id="模型与训练" tabindex="-1">模型与训练 <a class="header-anchor" href="#模型与训练" aria-label="Permalink to &quot;模型与训练&quot;">​</a></h4><ul><li><p><strong>Hugging Face Model Cards</strong>（地址：<a href="https://huggingface.co/docs/hub/en/model-cards" target="_blank" rel="noreferrer">https://huggingface.co/docs/hub/en/model-cards</a>）</p><ul><li>学习如何阅读模型卡，核对许可证、用途限制、训练数据说明和推荐用法。</li><li>下载模型前先看这一类信息。</li></ul></li><li><p><strong>Diffusers LoRA 训练</strong>（地址：<a href="https://huggingface.co/docs/diffusers/en/training/lora" target="_blank" rel="noreferrer">https://huggingface.co/docs/diffusers/en/training/lora</a>）</p><ul><li>理解 LoRA 训练的官方技术路线，了解训练脚本、数据集、显存和参数之间的关系。</li><li>适合有一定 Python 和命令行基础后再看。</li></ul></li><li><p><strong>kohya-ss/sd-scripts</strong>（地址：<a href="https://github.com/kohya-ss/sd-scripts" target="_blank" rel="noreferrer">https://github.com/kohya-ss/sd-scripts</a>）</p><ul><li>查看常见 LoRA 训练脚本和参数说明，学习训练前的数据准备、模型选择和输出格式。</li><li>适合进阶用户，不建议在没理解模型卡和许可证前直接照抄训练流程。</li></ul></li></ul><h4 id="中文补充" tabindex="-1">中文补充 <a class="header-anchor" href="#中文补充" aria-label="Permalink to &quot;中文补充&quot;">​</a></h4><ul><li><strong>ComfyUI Wiki 中文基础教程（社区资料）</strong>（地址：<a href="https://comfyui-wiki.com/zh/tutorial/basic" target="_blank" rel="noreferrer">https://comfyui-wiki.com/zh/tutorial/basic</a>） <ul><li>用中文快速了解 ComfyUI 基础流程，作为官方文档之外的补充阅读。</li><li>遇到版本差异时，以 ComfyUI 官方文档和实际节点为准。</li></ul></li></ul><h4 id="进阶与版本敏感资料" tabindex="-1">进阶与版本敏感资料 <a class="header-anchor" href="#进阶与版本敏感资料" aria-label="Permalink to &quot;进阶与版本敏感资料&quot;">​</a></h4><ul><li><p><strong>ComfyUI FLUX.1 文生图</strong>（地址：<a href="https://docs.comfy.org/zh/tutorials/flux/flux-1-text-to-image" target="_blank" rel="noreferrer">https://docs.comfy.org/zh/tutorials/flux/flux-1-text-to-image</a>）</p><ul><li>学习 FLUX.1 在 ComfyUI 中的基础文生图流程，了解新模型对文件、节点和显存的要求。</li><li>适合已经跑通过 SDXL 或基础 ComfyUI 流程后再看。</li></ul></li><li><p><strong>ComfyUI FLUX.2 Klein 指南</strong>（地址：<a href="https://docs.comfy.org/zh/tutorials/flux/flux-2-klein" target="_blank" rel="noreferrer">https://docs.comfy.org/zh/tutorials/flux/flux-2-klein</a>）</p><ul><li>了解 FLUX.2 Klein 的 ComfyUI 使用方式，对比新模型与传统 Stable Diffusion 工作流的差别。</li><li>这类教程版本变化快，使用前要确认模型文件和节点版本。</li></ul></li></ul><p>如果刚开始学 AI 绘画，建议按这个顺序看：先用 ComfyUI 官方教程跑通文生图；再学习 LoRA、ControlNet 和工作流示例；最后再看模型卡、许可证和训练资料。教程更新很快，阅读时注意教程发布时间、工具版本、模型版本、节点版本和下载来源。</p><h3 id="怎么判断教程质量" tabindex="-1">怎么判断教程质量 <a class="header-anchor" href="#怎么判断教程质量" aria-label="Permalink to &quot;怎么判断教程质量&quot;">​</a></h3><p>挑教程时用这几条原则过一遍，能滤掉大半过时和低质资料：</p><ul><li>优先看官方文档和官方示例。</li><li>优先选择写清楚模型版本、工具版本、节点版本和参数的教程。</li><li>下载模型前先读模型卡和许可证。</li><li>不把未知来源模型、素材或训练数据用于公开或商业项目。</li><li>视频教程可以用来熟悉操作，但具体参数和链接要回到官方资料核对。</li></ul><h3 id="怎么把教程变成自己的练习" tabindex="-1">怎么把教程变成自己的练习 <a class="header-anchor" href="#怎么把教程变成自己的练习" aria-label="Permalink to &quot;怎么把教程变成自己的练习&quot;">​</a></h3><p>看懂不等于会做，把教程变成练习有三个动作：</p><ul><li><strong>跟一遍，再改一遍</strong>：先严格照教程跑通，再把示例换成自己的素材或任务重做一次，差异就是理解缺口。</li><li><strong>记录版本与参数</strong>：把教程标题、链接、访问日期、工具与模型版本、关键参数记进笔记，以后排查问题先查这份记录。</li><li><strong>一次只改一个变量</strong>：教程跑通后固定其他条件，单独调一个参数看结果变化，把“教程结论”验证成“自己的结论”。</li></ul><h2 id="动手试试-跟完一个教程的正确姿势" tabindex="-1">动手试试：跟完一个教程的正确姿势 <a class="header-anchor" href="#动手试试-跟完一个教程的正确姿势" aria-label="Permalink to &quot;动手试试：跟完一个教程的正确姿势&quot;">​</a></h2><ol><li>选定一个与当前目标匹配的教程，先通读一遍，确认教程版本与自己的环境对得上。</li><li>建立记录：把教程标题、链接、访问日期、工具与模型版本写进笔记。</li><li>严格照做第一遍，只跑通最小流程，不中途加戏。</li><li>跑通后固定其他条件，一次只改一个变量做对照，并记录结果。</li><li>把成功配置与失败报错都存档，各写一句“这个教程教会我什么”。</li><li>隔一段时间回查官方文档，确认教程结论没有过时。</li></ol><h2 id="对比表" tabindex="-1">对比表 <a class="header-anchor" href="#对比表" aria-label="Permalink to &quot;对比表&quot;">​</a></h2><p>三种常见教程载体各有分工，按阶段配合使用：</p><table tabindex="0"><thead><tr><th>维度</th><th>视频教程</th><th>图文教程</th><th>官方文档</th></tr></thead><tbody><tr><td>上手方式</td><td>跟着画面操作，最直观</td><td>按步骤照做，可回查</td><td>系统读完，偏参考</td></tr><tr><td>信息密度</td><td>低，节奏由视频决定</td><td>中，可跳读可检索</td><td>高，覆盖参数最全</td></tr><tr><td>版本时效</td><td>最易过期，注意发布时间</td><td>看更新记录与评论</td><td>随版本更新，最可靠</td></tr><tr><td>适合阶段</td><td>熟悉界面与操作流程</td><td>第一次跑通完整流程</td><td>核对参数与排查问题</td></tr><tr><td>主要风险</td><td>截图与当前版本对不上</td><td>转载版可能被改动</td><td>对零基础偏枯燥</td></tr></tbody></table><p>常见配合：先用视频或图文跑通流程，再回官方文档核对参数、补齐原理。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li><strong>“收藏了教程、倍速看完就等于学会了”</strong>：收藏和倍速都只是完成了“看过”，能复述、能动手做出产出才算学会。</li><li><strong>“最新教程一定最好”</strong>：新教程常配套新模型、新节点，与你的环境和已有资料未必匹配，先看版本再决定；社区教程与官方文档说法冲突时，参数与兼容性以官方为准，社区经验用来补充操作细节。</li><li><strong>“照抄训练脚本就能练出好 LoRA”</strong>：数据准备、标注和版本配套比脚本本身更关键，进阶训练前先懂模型卡和许可证。</li><li><strong>“下载来源无所谓，能出图就行”</strong>：来源不明的模型与素材有安全与许可风险，下载前先看模型卡和许可证。</li></ul><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><h3 id="_1-你想学-lora-训练-面前有社区视频教程、comfyui-官方文档和-kohya-ss-的-github-仓库-先看哪个-为什么" tabindex="-1">1. 你想学 LoRA 训练，面前有社区视频教程、ComfyUI 官方文档和 kohya-ss 的 GitHub 仓库，先看哪个？为什么？ <a class="header-anchor" href="#_1-你想学-lora-训练-面前有社区视频教程、comfyui-官方文档和-kohya-ss-的-github-仓库-先看哪个-为什么" aria-label="Permalink to &quot;1. 你想学 LoRA 训练，面前有社区视频教程、ComfyUI 官方文档和 kohya-ss 的 GitHub 仓库，先看哪个？为什么？&quot;">​</a></h3><details><summary>查看答案</summary><p>先看官方资料定基准：官方文档讲清 LoRA 加载与参数含义，kohya-ss 仓库提供训练脚本与参数说明；社区视频只作操作演示的补充。训练类教程版本敏感，参数以官方说明为准，来源不明或版本不符的照抄容易翻车。</p></details><h3 id="_2-一篇图文教程跑不通-应该按什么顺序排查" tabindex="-1">2. 一篇图文教程跑不通，应该按什么顺序排查？ <a class="header-anchor" href="#_2-一篇图文教程跑不通-应该按什么顺序排查" aria-label="Permalink to &quot;2. 一篇图文教程跑不通，应该按什么顺序排查？&quot;">​</a></h3><details><summary>查看答案</summary><p>先看报错信息指出缺什么；再核对教程发布时间与你的工具、模型、节点版本是否一致；然后确认模型文件、VAE 等配套件是否齐全、下载来源是否正确；最后回到官方文档核对参数。仍不通时，换官方示例工作流做基准，再定位差异。</p></details><h3 id="_3-怎么判断一篇教程讲的是不是你手上这个版本" tabindex="-1">3. 怎么判断一篇教程讲的是不是你手上这个版本？ <a class="header-anchor" href="#_3-怎么判断一篇教程讲的是不是你手上这个版本" aria-label="Permalink to &quot;3. 怎么判断一篇教程讲的是不是你手上这个版本？&quot;">​</a></h3><details><summary>查看答案</summary><p>看三点：教程是否写明工具版本、模型版本和节点版本；发布或更新时间距今多久；界面截图、参数名与你手上的版本是否对得上。对不上就以官方当前文档为准，不要硬套教程参数。</p></details><h2 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to &quot;关联阅读&quot;">​</a></h2><ul><li><strong>核对来源：</strong> <a href="/resources/websites">常用网站</a>汇总官方站点、模型平台与研究入口。</li><li><strong>选择工具：</strong> <a href="/tools/common-tools">常用工具</a>帮助判断教程使用的工具是否适合当前任务。</li><li><strong>随时查词：</strong> <a href="/glossary">术语表</a>解释 checkpoint、CFG、触发词等常见术语。</li></ul><h2 id="官方或原始资料来源" tabindex="-1">官方或原始资料来源 <a class="header-anchor" href="#官方或原始资料来源" aria-label="Permalink to &quot;官方或原始资料来源&quot;">​</a></h2><ul><li><a href="https://developers.google.com/machine-learning/crash-course/llm" target="_blank" rel="noreferrer">Google LLM 入门课程</a>：Google 官方机器学习速成课程中的 LLM 单元。</li><li><a href="https://huggingface.co/learn/llm-course/chapter1/1" target="_blank" rel="noreferrer">Hugging Face LLM Course</a>：Hugging Face 官方 LLM 系统课程。</li><li><a href="https://docs.comfy.org/zh" target="_blank" rel="noreferrer">ComfyUI 官方中文文档</a>：ComfyUI 官方维护的中文文档与教程入口。</li><li><a href="https://huggingface.co/docs/hub/en/model-cards" target="_blank" rel="noreferrer">Hugging Face Model Cards 文档</a>：模型卡阅读与撰写的官方文档。</li><li><a href="https://huggingface.co/docs/diffusers/en/training/lora" target="_blank" rel="noreferrer">Hugging Face Diffusers LoRA 训练文档</a>：LoRA 训练的官方实践文档。</li><li><a href="https://comfyanonymous.github.io/ComfyUI_examples/" target="_blank" rel="noreferrer">ComfyUI 官方示例工作流</a>：ComfyUI 作者维护的官方示例集。</li></ul>',51)])])}const d=r(o,[["render",i]]);export{f as __pageData,d as default};
